// design-lab's pane: where a run is and when it is done, from the files the run writes. It reads
// only run folders (and, to find them, the person's design-lab settings, the project's runs folder
// and the active-run pointer), writes nothing to disk, and asks nothing of the person except, when
// the runner has stopped, a button that puts the resume request in the prompt.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { Summary } from '../../types'
import {
  afterFill, barOf, CHECK_COLORS, CHECK_MARKS, checkMessage, compactOf, durationOf, elapsedOf, failureOf, needsYouOf, parseJson,
  percentOf, PHASE_DONE, phaseLabel, plainOf, RESUME_PROMPT, isIdle, runnerLine, stagesOf, statusOf, stepsLine,
  summaryOf, toneOf, verdictOf,
} from './model'
import { ancestors, base, MARKERS, parent } from './locate'

const PANE = 'design-lab'
const COMMAND = 'design-lab:watch'
const RECAP_COMMAND = 'design-lab:recap'
// The skills that start or resume a run: each opens the pane by itself, so nobody has to know
// about design-lab:watch to see where a run is.
export const RUN_SKILLS = ['design-lab:run', 'design-lab:figma-build'] as const
export const POLL_MS = 5_000
// The runner log is tailed only while it is small enough to read whole every poll.
const LOG_READ_LIMIT = 1024 * 1024

const runAtom = atom({ plugin: 'design-lab', key: 'run' } as const, null)
const summaryAtom = atom({ plugin: 'design-lab', key: 'summary' } as const, null)
const alarmedAtom = atom({ plugin: 'design-lab', key: 'alarmed' } as const, false)
// The runs folder the pane follows when the person named no run: it moves to each newer run there.
const followAtom = atom({ plugin: 'design-lab', key: 'follow' } as const, null)
// A finished run the pane passes over while a run skill is starting the next one, so the pane
// never shows the last run's recap as if it were the new run.
const skipAtom = atom({ plugin: 'design-lab', key: 'skip' } as const, null)
// Whether a finished run's full completion message is open under its figures.
// Named by run, so opening one run's recap never opens the next run's.
const recapOpenAtom = atom({ plugin: 'design-lab', key: 'recapOpen' } as const, null)

// The files read under a run folder, and nothing else there.
export const RUN_FILES = {
  project: 'project.json',
  phaseLog: 'phase-log.jsonl',
  progress: 'figma/progress.json',
  runnerLog: 'figma/runner.log',
  completion: 'benchmark/completion.md',
  scorecard: 'benchmark/scorecard.json',
  preflightChecks: 'preflight-checks.json',
  verifyReport: 'verify-report.json',
} as const

// The files a finished run links to, when they exist: a rebuild has no plan or components of its
// own unless it copied them.
export const ARTIFACT_FILES = {
  report: 'benchmark/report.html',
  verifyReport: 'verify-report.json',
  plan: 'plan.json',
  components: 'components.json',
  scorecard: 'benchmark/scorecard.json',
} as const

// The bar's fill by the color its Text would take, and its empty track.
const BAR_COLORS: Record<string, string> = { cyan: '#4fa8d6', green: '#3fb36b', yellow: '#d6b44f', red: '#d65f5f' }
const BAR_TRACK = '#8888884d'

/** A rounded progress bar, wide and short so it scales to the pane's width. */
function barSvg(share: number, fill: string): string {
  const filled = share > 0 ? `<rect width="${Math.max(12, share)}" height="12" rx="6" fill="${fill}"/>` : ''
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="12" viewBox="0 0 1000 12">`
    + `<rect width="1000" height="12" rx="6" fill="${BAR_TRACK}"/>${filled}</svg>`
}

let timer: Timer | undefined
// The last JSON that parsed, so a file caught half-written keeps the last good reading.
const lastGood = new Map<string, unknown>()

async function readText($: EngineInterface, path: string): Promise<string | undefined> {
  try {
    return await $.fs.read(path)
  } catch {
    return undefined
  }
}

async function readJson($: EngineInterface, path: string): Promise<unknown> {
  const value = parseJson(await readText($, path))
  if (value !== undefined) lastGood.set(path, value)
  return value ?? lastGood.get(path)
}

async function readLog($: EngineInterface, path: string): Promise<string | undefined> {
  try {
    const stat = await $.fs.stat(path)
    return stat.size <= LOG_READ_LIMIT ? await $.fs.read(path) : undefined
  } catch {
    return undefined
  }
}

export async function summarise($: EngineInterface, run: string): Promise<Summary> {
  const at = (file: string) => `${run}/${file}`
  const raw = {
    project: await readJson($, at(RUN_FILES.project)),
    phaseLog: await readText($, at(RUN_FILES.phaseLog)),
    progress: await readJson($, at(RUN_FILES.progress)),
    preflightChecks: await readJson($, at(RUN_FILES.preflightChecks)),
    verifyReport: await readJson($, at(RUN_FILES.verifyReport)),
    runnerLog: await readLog($, at(RUN_FILES.runnerLog)),
    ...((await $.fs.exists(at(RUN_FILES.completion)))
      ? { completion: await readText($, at(RUN_FILES.completion)), scorecard: await readJson($, at(RUN_FILES.scorecard)),
        present: await presentOf($, run) }
      : {}),
  }
  return summaryOf(run, raw, await $.clock.now())
}

/** Which of the run's artifact files exist, so the pane links only to those. */
async function presentOf($: EngineInterface, run: string): Promise<string[]> {
  const found: string[] = []
  for (const path of Object.values(ARTIFACT_FILES)) if (await exists($, `${run}/${path}`)) found.push(path)
  return found
}

let refreshing = false

async function refresh($: EngineInterface): Promise<void> {
  // A slow file system must not stack refreshes: skip a tick while the last one is still reading.
  if (refreshing) return
  refreshing = true
  try {
    await refreshNow($)
  } finally {
    refreshing = false
  }
}

async function refreshNow($: EngineInterface): Promise<void> {
  const follow = await read($, followAtom)
  if (follow) {
    const newest = await newestRun($, follow)
    if (newest && newest !== (await read($, skipAtom)) && newest !== (await read($, runAtom))) {
      await update($, runAtom, () => newest)
      await update($, skipAtom, () => null)
      await update($, alarmedAtom, () => false)
    }
  }
  const run = await read($, runAtom)
  if (!run) return
  const summary = await summarise($, run)
  const before = await read($, summaryAtom)
  if (JSON.stringify(before) !== JSON.stringify(summary)) await update($, summaryAtom, () => summary)
  $.ui.status(statusOf(summary, await $.clock.now()))
  // Done: say so once, the moment the recap appears.
  if (summary.hasRecap && before && before.found && !before.hasRecap) {
    // Say what the header says: a run that left problems open is done but needs review.
    const review = verdictOf(summary.findings) ? ', with verification problems to review' : ''
    $.ui.toast(`design-lab: ${summary.siteLabel ?? 'the run'} is done${review}. The recap is in the design-lab pane.`, { timeoutMs: 10_000 })
  }
  // The watchdog: once per transition, never again until the run needs nothing from the person.
  // It says what the Needs you card says.
  const need = needsYouOf(summary)
  const alarmed = await read($, alarmedAtom)
  if (need && !alarmed) {
    $.ui.toast(`design-lab needs you: ${need.message}`, { timeoutMs: 10_000 })
    await update($, alarmedAtom, () => true)
  } else if (!need && alarmed) {
    await update($, alarmedAtom, () => false)
  }
}

function watch($: EngineInterface): void {
  timer?.cancel()
  timer = $.clock.every(POLL_MS, () => void refresh($))
}

/** The run a command names, or with none: the newest in this project's runs folder, which the pane
 * then follows; else the run the machine-wide pointer names. */
async function runOf($: EngineInterface, args: string): Promise<string | { missing: string; follow?: string }> {
  const given = args.trim()
  if (given) return given.startsWith('/') ? given.replace(/\/+$/, '') : `${await $.session.cwd()}/${given}`
  const folder = await runsFolder($, await $.session.cwd())
  if (folder) {
    const newest = await newestRun($, folder)
    return newest ?? { missing: `No design-lab run yet in ${folder}. The pane shows the first one as soon as it starts.`, follow: folder }
  }
  const home = await $.env.get('HOME')
  const pointer = parseJson(home ? await readText($, `${home}/.design-lab/active-run.json`) : undefined)
  const workspace = typeof pointer === 'object' && pointer !== null ? (pointer as { workspace?: unknown }).workspace : undefined
  if (typeof workspace === 'string') return workspace
  return { missing: (await settings($)).convention
    ? 'No design-lab run found for this folder. Give the run folder: /design-lab:watch <run folder>'
    : 'design-lab is not set up on this machine yet: run design-lab:init once. Or give the run folder: /design-lab:watch <run folder>' }
}

// Which run to watch when the person names none: the newest in this project's runs folder, by
// the convention design-lab:init recorded (scripts/lab_config.py holds the same rule).

async function exists($: EngineInterface, path: string): Promise<boolean> {
  return $.fs.exists(path).catch(() => false)
}

async function isDir($: EngineInterface, path: string): Promise<boolean> {
  const found = await $.fs.stat(path, { resolve: false }).catch(() => undefined)
  return found?.kind === 'dir'
}

async function hasMarker($: EngineInterface, folder: string): Promise<boolean> {
  for (const marker of MARKERS) if (await isDir($, `${folder}/${marker}`)) return true
  return false
}

/** A path with every link followed, as the scripts resolve it; the path itself when it cannot be. */
async function real($: EngineInterface, path: string): Promise<string> {
  const found = await $.fs.stat(path, { resolve: true }).catch(() => undefined)
  return (found?.realPath ?? path).replace(/\/+$/, '') || '/'
}

/** The person's design-lab settings, or {} before design-lab:init has run. */
async function settings($: EngineInterface): Promise<{ convention?: string; home?: string }> {
  const rawHome = await $.env.get('HOME')
  const home = rawHome ? await real($, rawHome) : undefined
  const path = (await $.env.get('DESIGN_LAB_CONFIG')) ?? (home ? `${home}/.claude/design-lab.json` : undefined)
  const text = path ? await $.fs.read(path).catch(() => undefined) : undefined
  const value = parseJson(typeof text === 'string' ? text : undefined) as { runs?: { convention?: unknown } } | undefined
  const convention = typeof value?.runs?.convention === 'string' ? value.runs.convention : undefined
  return { convention, home }
}

/** The project folder for a session in `cwd`: above worktrees/ for PROJECT/worktrees/<name>,
 * else the nearest folder above the repository holding plans/, analysis-reports/ or design/. */
async function projectFolder($: EngineInterface, cwd: string, home?: string): Promise<string | undefined> {
  const stop = (folder: string) => folder === '/' || folder === home
  const chain = ancestors(cwd)
  let repo: string | undefined
  for (const folder of chain) if (await exists($, `${folder}/.git`)) { repo = folder; break }
  if (!repo) {
    for (const folder of chain) {
      if (stop(folder)) return undefined
      if (await isDir($, `${folder}/worktrees`) || await hasMarker($, folder)) return folder
    }
    return undefined
  }
  if (base(parent(repo)) === 'worktrees') return parent(parent(repo))
  for (const folder of ancestors(parent(repo))) {
    if (stop(folder)) return undefined
    if (await hasMarker($, folder)) return folder
  }
  return undefined
}

/** Where this project's runs live, or undefined when design-lab:init has not chosen. */
async function runsFolder($: EngineInterface, sessionCwd: string): Promise<string | undefined> {
  const { convention, home } = await settings($)
  const cwd = await real($, sessionCwd)
  const project = await projectFolder($, cwd, home)
  if (convention === 'project') return project ? `${project}/design` : undefined
  if (convention === 'home' && home) {
    let repo: string | undefined
    for (const folder of ancestors(cwd)) if (await exists($, `${folder}/.git`)) { repo = folder; break }
    return `${home}/.design/${base(project ?? repo ?? cwd)}`
  }
  return undefined
}

// When each run began, read once per run folder: a run's start never changes, so a poll lists the
// runs folder and reads only the project.json of runs it has not seen.
const startedAt = new Map<string, string>()

/** The newest run in a runs folder: latest start (project.json createdAt), then folder name. */
async function newestRun($: EngineInterface, folder: string): Promise<string | undefined> {
  const entries = await $.fs.list(folder).catch(() => [])
  let best: { created: string; name: string; path: string } | undefined
  for (const entry of entries) {
    if (entry.kind !== 'dir') continue
    const path = `${folder}/${entry.name}`
    let created = startedAt.get(path)
    if (created === undefined) {
      const text = await $.fs.read(`${path}/project.json`).catch(() => undefined)
      const value = (parseJson(typeof text === 'string' ? text : undefined) as { createdAt?: unknown } | undefined)?.createdAt
      if (typeof value !== 'string') continue
      startedAt.set(path, value)
      created = value
    }
    if (!best || created > best.created || (created === best.created && entry.name > best.name)) {
      best = { created, name: entry.name, path }
    }
  }
  return best?.path
}

/** A run skill is starting: follow this project's runs folder and open the pane beside the
 * conversation. A newest run with no recap yet is the one being resumed, so it shows at once; a finished
 * one is passed over until the new run's folder appears. Opened from the person's own slash
 * command, Claude Code places the pane at any width; from the Skill tool, only in a wide window. */
async function followRunSkill($: EngineInterface): Promise<void> {
  const folder = await runsFolder($, await $.session.cwd())
  // Not set up yet: the skill sends the person to design-lab:init first.
  if (!folder) return
  const newest = await newestRun($, folder)
  const summary = newest ? await summarise($, newest) : undefined
  const resuming = newest && summary?.found && !summary.hasRecap ? newest : null
  await update($, followAtom, () => folder)
  await update($, skipAtom, () => resuming ? null : newest ?? null)
  await update($, runAtom, () => resuming)
  await update($, summaryAtom, () => resuming ? summary! : null)
  await update($, alarmedAtom, () => false)
  watch($)
  if (resuming) void refresh($)
  if ((await $.session.surfaces()).length > 0) await $.ui.open({ id: PANE, title: 'design-lab' }).catch(() => undefined)
}

async function resume($: EngineInterface, run: string): Promise<void> {
  const text = RESUME_PROMPT(run)
  const step = afterFill(await $.prompt.fill({ text, mode: 'replace' }).catch(() => undefined))
  if (step === 'submit') await $.prompt.submit({ text }).catch(() => undefined)
  if (step === 'explain') $.ui.toast('design-lab: close the open dialog, then press resume again.')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // After a reload the run is still in state; pick the watch back up.
    if ((await read($, runAtom)) || (await read($, followAtom))) {
      watch($)
      void refresh($)
    }
    return next(e)
  })

  on('session.end', async (_$, e, next) => {
    timer?.cancel()
    timer = undefined
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const run = await runOf($, e.args)
    // Named, a run is watched as named; found by convention, the pane follows the runs folder.
    const follow = e.args.trim() ? null : typeof run === 'string'
      ? (await runsFolder($, await $.session.cwd())) ?? null : run.follow ?? null
    await update($, followAtom, () => follow)
    await update($, skipAtom, () => null)
    if (typeof run !== 'string') {
      if (!follow) return { text: run.missing }
      await update($, runAtom, () => null)
      await update($, summaryAtom, () => null)
      watch($)
      if ((await $.session.surfaces()).length > 0) await $.ui.open({ id: PANE, title: 'design-lab', focus: true })
      return { text: run.missing }
    }
    await update($, runAtom, () => run)
    await update($, alarmedAtom, () => false)
    await refresh($)
    watch($)
    const summary = (await read($, summaryAtom)) ?? (await summarise($, run))
    if ((await $.session.surfaces()).length === 0) return { text: plainOf(summary) }
    // The person asked for it: bring it to the front, over any other pane already open.
    const opened = await $.ui.open({ id: PANE, title: 'design-lab', focus: true })
    return { text: opened.isPlaced ? `Watching ${summary.siteLabel ?? run}.` : plainOf(summary) }
  })

  // Typed as a slash command: the person asked, so the pane opens at any width.
  for (const command of RUN_SKILLS) {
    on('command.run', { command }, async ($, e, next) => {
      await followRunSkill($).catch(() => undefined)
      return next(e)
    })
  }

  // Called through the Skill tool (the person asked in their own words): the same, unasked. A typed
  // command raises this too, after command.run; following again then changes nothing.
  on('skill.prompt', async ($, e, next) => {
    if ((RUN_SKILLS as readonly string[]).includes(e.skill)) {
      await followRunSkill($).catch(() => undefined)
    }
    return next(e)
  })

  on('command.run', { command: RECAP_COMMAND }, async ($, e) => {
    const run = await runOf($, e.args)
    if (typeof run !== 'string') return { text: run.missing }
    const summary = await summarise($, run)
    if (!summary.found) return { text: plainOf(summary) }
    return { text: summary.recap ?? `${summary.siteLabel ?? run} has no recap yet: the run has not finished its benchmark.` }
  })

  // The recap's output row, drawn as the Markdown it is, so its links are links.
  on('ui.render', { component: 'CommandOutput', props: { command: RECAP_COMMAND } }, async ($, e, next) => {
    if (!e.props.text) return next(e)
    const { Markdown } = $.ui.resolve(e)
    return <Markdown text={e.props.text} />
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const elements = $.ui.resolve(e)
    const { Box, Text, Button, Markdown } = elements
    // Drawn surfaces (desktop, editor, phone) draw the bar as a vector; the terminal as cells.
    const Svg = e.surface !== 'terminal' && 'Svg' in elements ? elements.Svg : undefined
    const summary = await read($, summaryAtom)
    const run = await read($, runAtom)
    // The pane's ✕ sits on its first row: start one row lower so it never covers text.
    const follow = await read($, followAtom)
    if (!summary || !run) {
      const skip = await read($, skipAtom)
      return <Box marginTop={1} flexDirection="column" gap={1}>
        <Text bold>design-lab</Text>
        <Text dimColor>{follow
          ? skip
            ? 'Waiting for the new design-lab run to start. It appears here as soon as its folder is made.'
            : `No design-lab run yet in ${follow}. It appears here as soon as one starts.`
          : 'No design-lab run is being watched.'}</Text>
      </Box>
    }
    if (!summary.found) return <Box marginTop={1}><Text>{plainOf(summary)}</Text></Box>
    const now = await $.clock.now()
    const columns = e.props.bodyColumns
    // The card around the bar takes margin 2, border 2 and padding 2; the rest is slack.
    const width = Math.max(4, columns - 10)
    const tone = toneOf(summary)
    const stages = stagesOf(summary)
    const need = needsYouOf(summary)
    const failure = failureOf(summary)
    const runner = summary.runner
    const preflight = summary.preflight
    const scores = summary.scores
    const finished = summary.hasRecap
    const verdict = finished ? verdictOf(summary.findings) : null
    const recapOpen = (await read($, recapOpenAtom)) === run
    const time = finished ? durationOf(scores?.workingSeconds ?? null) : elapsedOf(summary.startedAt, now)
    const name = run.split('/').pop()
    // Finished with figures, the Time tile holds the time, so the subtitle does not repeat it.
    const subtitle = finished && scores ? [name] : [name, time && `${time} ${finished ? 'working time' : 'elapsed'}`]
    // Two tiles side by side need about 52 columns; narrower, they stack.
    const narrowTiles = columns < 52
    // Narrower still, a stage's steps go one per line.
    const narrowSteps = columns < 40

    // One figure in a quietly bordered tile: only the value carries color, so the tiles never
    // compete with a card that asks for attention.
    const tile = (key: string, label: string, value: string | null, details: (string | null)[], color: string | undefined) => (
      <Box key={`tile-${key}`} flexDirection="column" flexGrow={1} flexShrink={1} width={narrowTiles ? '100%' : '50%'}
        borderStyle="round" borderDimColor paddingX={1}>
        <Text dimColor>{label}</Text>
        <Text bold color={color}>{value ?? '–'}</Text>
        {details.filter(Boolean).map((detail, i) => <Text key={`${key}-${i}`} dimColor wrap="wrap">{detail}</Text>)}
      </Box>
    )
    // Coverage and accuracy are judgments: green only when nothing is missing, yellow otherwise.
    const judged = (share: number | null) => share === null ? undefined : share >= 100 ? 'green' : 'yellow'
    const progress = (done: number, total: number, color: string) => {
      if (Svg) {
        const share = Math.round(Math.min(1, Math.max(0, total > 0 ? done / total : 0)) * 1000)
        return <Svg alt={`${done} of ${total} steps`} source={barSvg(share, BAR_COLORS[color] ?? BAR_COLORS.cyan!)} />
      }
      const bar = barOf(done, total, width)
      return <Text wrap="truncate-end"><Text color={color}>{bar.filled}</Text><Text dimColor>{bar.empty}</Text></Text>
    }
    // A stage's phases as ticks: done, failed, under way (or waiting on the person), still to come.
    const steps = (phases: { name: string; status: string }[], stopped: boolean) => {
      const ticks = phases.map(phase => {
        const done = PHASE_DONE.has(phase.status)
        const failed = phase.status === 'failed'
        const current = phase.name === summary.current || phase.status === 'running'
        const color = done ? 'green' : failed ? 'red' : current ? (stopped ? 'yellow' : 'cyan') : undefined
        const mark = done ? '✓' : failed ? '✗' : current ? (stopped ? '!' : '▸') : '○'
        return { key: phase.name, color, current, quiet: !done && !failed && !current, text: `${mark} ${phaseLabel(phase.name)}` }
      })
      if (narrowSteps) {
        return <Box flexDirection="column">{ticks.map(t =>
          <Text key={t.key} color={t.color} dimColor={t.quiet} bold={t.current} wrap="truncate-end">{t.text}</Text>)}</Box>
      }
      return <Text wrap="wrap">{ticks.map((t, i) =>
        <Text key={t.key} color={t.color} dimColor={t.quiet} bold={t.current}>{i > 0 ? '  ' : ''}{t.text}</Text>)}</Text>
    }

    // What the open stage shows beneath its row: only the detail that stage needs.
    const detail = (id: string, state: string, phases: { name: string; status: string }[]) => {
      if (id === 'preflight') {
        return preflight?.checks
          ? preflight.checks.map(check => {
            const message = checkMessage(check)
            return (
              <Box key={`check-${check.id}`} flexDirection="column">
                <Text dimColor={check.status === 'waiting'} color={CHECK_COLORS[check.status]}>
                  {CHECK_MARKS[check.status] ?? '·'} {check.label}
                </Text>
                {message && <Text dimColor={check.status === 'checking'}>  {message}</Text>}
              </Box>
            )
          })
          : <Text dimColor>Checking the site, the tools and the Figma file.</Text>
      }
      if (id === 'build') {
        const stopped = state === 'stopped'
        const building = runner && runner.state === 'building' && runner.stepsTotal
        // Stopped, the Needs you card says what to do; the step count would only repeat the bar.
        const line = !runner || stopped || state === 'failed' ? null
          : runner.stepsTotal && (runner.state === 'building' || runner.state === 'done')
            ? `${runner.stepsDone ?? 0} of ${runner.stepsTotal} steps` : stepsLine(runner)
        return (
          <Box flexDirection="column" gap={1}>
            {steps(phases, stopped)}
            {(building || line) && runner && (
              <Box flexDirection="column">
                {building && progress(runner.stepsDone ?? 0, runner.stepsTotal!, stopped ? 'yellow' : state === 'failed' ? 'red' : 'cyan')}
                {line && <Text dimColor wrap="truncate-end">{line}</Text>}
              </Box>
            )}
            {runner && (
              <Text wrap="truncate-end">
                <Text color={runner.connected || runner.state === 'done' ? 'green' : isIdle(runner) ? 'gray' : 'yellow'}>● </Text>
                <Text dimColor={isIdle(runner)}>{runnerLine(runner)}</Text>
              </Text>
            )}
          </Box>
        )
      }
      if (id === 'verify') return <Text dimColor>Checking the file against the design-lab standard.</Text>
      if (id === 'report') return <Text dimColor>Scoring the run and writing the report.</Text>
      return steps(phases, state === 'stopped')
    }

    const MARK: Record<string, string> = { done: '✓', flagged: '!', active: '▸', stopped: '!', failed: '✗', pending: '○', reused: '↺' }
    const COLOR: Record<string, string | undefined> = {
      done: 'green', flagged: 'yellow', active: 'cyan', stopped: 'yellow', failed: 'red', pending: undefined, reused: undefined,
    }
    // One card opens: a failure first, then a stop for the person, then the first stage under way.
    const opened = stages.find(stage => stage.state === 'failed') ?? stages.find(stage => stage.state === 'stopped')
      ?? stages.find(stage => stage.state === 'active')

    return (
      <Box flexDirection="column" marginTop={1} gap={1}>
        {/* Header: what the run is, and where it stands in one colored word. */}
        <Box flexDirection="column">
          <Box flexDirection="row" justifyContent="space-between" alignItems="center">
            <Text bold wrap="truncate-end">{summary.siteLabel ?? run}</Text>
            <Text bold inverse color={tone.color}>{`\u00a0${tone.label}\u00a0`}</Text>
          </Box>
          <Text dimColor wrap="truncate-end">{subtitle.filter(Boolean).join(' · ')}</Text>
        </Box>

        {/* What went wrong, above everything else. */}
        {failure && (
          <Box key="failed" flexDirection="column" borderStyle="round" borderColor="red" paddingX={1}>
            <Text bold color="red">Failed</Text>
            <Text>{failure.text}</Text>
          </Box>
        )}

        {/* The one thing the person has to do. */}
        {need && (
          <Box key="needs-you" flexDirection="column" borderStyle="round" borderColor="yellow" paddingX={1}>
            <Text bold color="yellow">Needs you</Text>
            <Text>{need.message}</Text>
            {need.canResume && <Text dimColor>When the runner is open again, press Resume run.</Text>}
            {summary.facts.figmaUrl && <Markdown text={`[Open the Figma file ↗](${summary.facts.figmaUrl})`} />}
            {need.canResume && (
              <Box marginTop={1}>
                <Button key="resume" label="Resume run" onPress={() => void resume($, run)} />
              </Box>
            )}
          </Box>
        )}

        {/* The five stages, in order: one row each, the open one with its detail beneath. */}
        <Box flexDirection="column">
          {stages.map((stage, i) => {
            const lit = stage.state === 'active' || stage.state === 'stopped' || stage.state === 'failed'
            const color = COLOR[stage.state]
            return (
              <Box key={`stage-${stage.id}`} flexDirection="column">
                <Box flexDirection="row" justifyContent="space-between" gap={1}>
                  <Box flexShrink={0}>
                    <Text bold={lit} dimColor={stage.state === 'pending' || stage.state === 'reused'}
                      color={lit || stage.state === 'flagged' ? color : undefined}>
                      <Text color={color}>{MARK[stage.state]}</Text> {i + 1}  {stage.label}
                    </Text>
                  </Box>
                  {stage.note ? <Text color={stage.noteColor} dimColor={!stage.noteColor && !lit}
                    wrap={stage.id === 'verify' ? 'wrap' : 'truncate-end'}>{stage.note}</Text> : null}
                </Box>
                {opened === stage && (
                  // Stopped, the card stays quiet: the Needs you card is the only yellow box.
                  <Box key={`card-${stage.id}`} flexDirection="column" marginLeft={2} marginY={1} paddingX={1} borderStyle="round"
                    borderColor={stage.state === 'stopped' ? undefined : color} borderDimColor>
                    {detail(stage.id, stage.state, stage.phases)}
                  </Box>
                )}
              </Box>
            )
          })}
        </Box>

        {/* Finished: the verdict, the report's figures, then what the run made and where it is. */}
        {finished && (
          <Box flexDirection="column" gap={1}>
            {verdict && (
              <Box key="verdict" flexDirection="column" borderStyle="round" borderColor="yellow" paddingX={1}>
                <Text bold color="yellow">Verification found problems</Text>
                <Text>{verdict}</Text>
                <Markdown text={`[Open the verification findings](${fileUrl(run, ARTIFACT_FILES.verifyReport)})`} />
              </Box>
            )}
            {scores && (() => {
              const coverage = percentOf(scores.built, scores.eligible)
              const accuracy = percentOf(scores.withinTolerance, scores.widths)
              const missing = scores.built !== null && scores.eligible !== null && scores.eligible > scores.built
                ? `${scores.eligible - scores.built} not built` : null
              return (
                <Box flexDirection="column" gap={1}>
                  <Box flexDirection={narrowTiles ? 'column' : 'row'} gap={1}>
                    {tile('coverage', 'Coverage', coverage !== null ? `${coverage}%` : null,
                      [scores.built !== null && scores.eligible !== null ? `${scores.built} of ${scores.eligible} buildable` : null, missing],
                      judged(coverage))}
                    {tile('accuracy', 'Accuracy', accuracy !== null ? `${accuracy}%` : null,
                      [scores.withinTolerance !== null && scores.widths !== null ? `${scores.withinTolerance} of ${scores.widths} widths within tolerance` : null],
                      judged(accuracy))}
                  </Box>
                  <Box flexDirection={narrowTiles ? 'column' : 'row'} gap={1}>
                    {tile('time', 'Time', durationOf(scores.workingSeconds),
                      [scores.buildSeconds !== null ? `Figma build ${durationOf(scores.buildSeconds)}` : null], 'magenta')}
                    {tile('tokens', 'Tokens', compactOf(scores.tokens),
                      [scores.toolCalls !== null ? `${scores.toolCalls} tool calls` : null], 'blue')}
                  </Box>
                </Box>
              )
            })()}
            {(() => {
              const links = artifactsOf(run, summary.facts.figmaUrl, new Set(summary.present))
              return (links.main || links.files) && (
                <Box flexDirection="column" gap={1}>
                  {links.main && (
                    <Box flexDirection="column">
                      <Text bold dimColor>Results</Text>
                      <Markdown text={links.main} />
                    </Box>
                  )}
                  {links.files && (
                    <Box flexDirection="column">
                      <Text bold dimColor>Run files</Text>
                      <Markdown text={links.files} />
                    </Box>
                  )}
                </Box>
              )
            })()}
            {summary.recap && (
              <Box flexDirection="column">
                <Box flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Text bold dimColor>Recap</Text>
                  <Button key="recap" label={recapOpen ? 'Hide' : 'Show'} onPress={() => void update($, recapOpenAtom, open => open === run ? null : run)} />
                </Box>
                {recapOpen && <Markdown text={summary.recap} />}
              </Box>
            )}
          </Box>
        )}
      </Box>
    )
  })
}

/** A file in the run folder as a link: each path segment encoded, so a space, #, ? or bracket in a
 * folder name cannot end or break the link. */
export function fileUrl(run: string, path: string): string {
  const encode = (segment: string) => encodeURIComponent(segment).replace(/[!'()*]/g, c => `%${c.charCodeAt(0).toString(16).toUpperCase()}`)
  return `file://${`${run}/${path}`.split('/').map(encode).join('/')}`
}

/** What a finished run made, as links: the two that matter (the Figma file and the benchmark
 * report), then the run's own files. Only files that exist are listed. */
export function artifactsOf(run: string, figmaUrl: string | null, present: Set<string>): { main: string | null; files: string | null } {
  const main = [
    figmaUrl ? `**[Open the Figma library ↗](${figmaUrl})**` : null,
    present.has(ARTIFACT_FILES.report) ? `**[Open the benchmark report](${fileUrl(run, ARTIFACT_FILES.report)})**` : null,
  ].filter(Boolean)
  const files = ([
    ['Verification findings', ARTIFACT_FILES.verifyReport],
    ['Build plan', ARTIFACT_FILES.plan],
    ['Components', ARTIFACT_FILES.components],
    ['Scorecard', ARTIFACT_FILES.scorecard],
  ] as const).filter(([, path]) => present.has(path)).map(([label, path]) => `[${label}](${fileUrl(run, path)})`)
  // No bullets: Markdown indents them unevenly. The two results stand one per line (a hard break
  // is two trailing spaces); the run files share one line.
  return { main: main.length ? main.join('  \n') : null, files: files.length ? files.join(' · ') : null }
}

files.hooks/mod/model.ts:
// What a design-lab run looks like from the files it writes, with no engine calls: the same
// reading `workflow.py watch` does, so the pane and the text fallback agree.

import type { Check, Facts, Findings, Phase, Runner, Scores, Summary } from '../../types'

// Three missed heartbeats (figma_runner.HEARTBEAT_SECONDS is 10).
export const SERVER_FRESH_MS = 30_000
// workflow.py's RUNNER_ABSENT_MINUTES: the runner must have asked for a step within two minutes.
export const RUNNER_ABSENT_MS = 120_000
export const LOG_LINES = 8
// The Markdown element draws at most 10,000 characters.
export const RECAP_LIMIT = 9_500

const DONE = new Set(['complete', 'approved', 'waived'])

/** The files the mod reads, as text; a missing or unreadable file is undefined. */
export type Raw = {
  project?: unknown
  phaseLog?: string
  progress?: unknown
  runnerLog?: string
  completion?: string
  scorecard?: unknown
  preflightChecks?: unknown
  verifyReport?: unknown
  // the artifact files found in the run folder, run-relative
  present?: string[]
}

export function parseJson(text: string | undefined): unknown {
  if (text === undefined) return undefined
  try {
    return JSON.parse(text)
  } catch {
    return undefined
  }
}

function record(value: unknown): Record<string, unknown> {
  return typeof value === 'object' && value !== null ? (value as Record<string, unknown>) : {}
}

function text(value: unknown): string | null {
  return typeof value === 'string' ? value : null
}

function count(value: unknown): number | null {
  return typeof value === 'number' ? value : null
}

function msSince(stamp: string | null, nowMs: number): number | null {
  if (!stamp) return null
  const at = Date.parse(stamp)
  return Number.isNaN(at) ? null : nowMs - at
}

/** The phase log's lines that parse; a half-written last line is skipped. */
export function entriesOf(log: string | undefined): Record<string, unknown>[] {
  if (!log) return []
  return log.split('\n').flatMap(line => {
    const value = parseJson(line.trim() || undefined)
    return typeof value === 'object' && value !== null ? [value as Record<string, unknown>] : []
  })
}

export function tailOf(log: string | undefined, lines = LOG_LINES): string[] {
  if (!log) return []
  return log.split('\n').filter(line => line.trim() !== '').slice(-lines)
}

export function runnerOf(progress: unknown, nowMs: number): Runner | null {
  const p = record(progress)
  if (!('state' in p)) return null
  const serverAge = msSince(text(p.at), nowMs)
  const serverAlive = serverAge !== null && serverAge <= SERVER_FRESH_MS
  const seenAge = msSince(text(p.lastSeen), nowMs)
  const asked = seenAge !== null && seenAge <= RUNNER_ABSENT_MS
  const connected = serverAlive && (asked || p.inflight === true)
  return {
    state: text(p.state) ?? 'waiting',
    stepsDone: count(p.stepsDone),
    stepsTotal: count(p.stepsTotal),
    stepKind: text(p.stepKind),
    message: text(p.message),
    serverAlive,
    connected,
    lastSeenMs: seenAge,
  }
}

export function summaryOf(workspace: string, raw: Raw, nowMs: number): Summary {
  const project = record(raw.project)
  if (raw.project === undefined) {
    return { workspace, found: false, siteLabel: null, phases: [], current: null, preflight: null,
      runner: null, blocker: null, waiting: null, log: [], hasRecap: false, recap: null, scores: null,
      facts: { found: null, toBuild: null, built: null, expected: null, figmaUrl: null }, findings: null, startedAt: null,
      phaseErrors: {}, present: [] }
  }
  const recorded: Phase[] = Object.entries(record(project.phases)).map(([name, value]) => ({
    name, status: text(record(value).status) ?? 'pending', reused: Boolean(record(value).from),
  }))
  const finished = recapIsCurrent(project, raw)
  // Preflight records its phase only once it passes, so until then a run that has not reached the
  // build is still in preflight. A rebuild copies preflight from its source and never runs it here.
  const preflighting = !recorded.some(phase => phase.name === 'preflight') && !recorded.some(phase => phase.reused)
    && !finished && !recorded.some(phase => BUILD_PHASES.has(phase.name) && phase.status !== 'pending')
  // In the order the run takes them, not the order project.json happens to hold them.
  const phases = [...recorded, ...(preflighting ? [{ name: 'preflight', status: 'running', reused: false }] : [])]
    .sort((a, b) => flowRank(a.name) - flowRank(b.name))
  // A phase copied from an earlier run never takes the current phase, whatever status it copied.
  const own = phases.filter(phase => !phase.reused)
  const running = own.find(phase => phase.status === 'running')
  const due = own.find(phase => !DONE.has(phase.status))
  const runner = runnerOf(raw.progress, nowMs)
  const entries = entriesOf(raw.phaseLog)
  const last = entries[entries.length - 1]
  const phaseErrors: Record<string, string> = {}
  for (const phase of phases) {
    if (phase.status !== 'failed') continue
    const said = entries.filter(entry => entry.phase === phase.name && typeof entry.message === 'string').pop()
    if (said) phaseErrors[phase.name] = said.message as string
  }
  // The open blocker: the newest entry stopped the run for the person, and the runner has not
  // come back since.
  const blocker = last && last.status === 'stopped' && !runner?.connected ? text(last.message) : null
  // Waiting on the person for something the run notices by itself (the runner starting at the
  // build's connection): what to do, with nothing to press.
  const waiting = last && last.status === 'waiting' && !runner?.connected ? text(last.message) : null
  // While the build waits for the person to start the runner, the runner is awaited, not idle.
  const shown = waiting && runner && runner.state === 'waiting' ? { ...runner, state: 'connecting' } : runner
  const preflight = record(record(project.phases).preflight)
  const preflightAt = preflight.from ? null : text(preflight.updatedAt)
  const checks = checksOf(raw.preflightChecks, preflight)
  return {
    workspace,
    found: true,
    siteLabel: text(record(project.run).siteLabel),
    phases,
    current: (running ?? due)?.name ?? null,
    preflight: preflight.status || checks
      ? { status: text(preflight.status) ?? 'running', at: preflightAt, checks }
      : null,
    runner: shown,
    blocker,
    waiting,
    log: tailOf(raw.runnerLog),
    hasRecap: finished,
    recap: finished ? recapOf(raw.completion!) : null,
    scores: finished ? scoresOf(raw.scorecard) : null,
    facts: factsOf(project, finished ? raw.completion : undefined),
    findings: findingsOf(raw.verifyReport, text(project.createdAt)),
    startedAt: preflightAt ?? text(project.createdAt),
    phaseErrors,
    present: raw.present ?? [],
  }
}

export const CHECK_MARKS: Record<string, string> = { done: '✓', checking: '▸', 'needs-you': '!', failed: '✗', waiting: '·' }
export const CHECK_COLORS: Record<string, string | undefined> = { done: 'green', checking: 'cyan', 'needs-you': 'yellow', failed: 'red' }

/** The checklist preflight last wrote, or null when there is none or it is older than the recorded
 * preflight phase (a run that passed preflight before the checklist existed). */
export function checksOf(document: unknown, phase: Record<string, unknown>): Check[] | null {
  const d = record(document)
  if (!Array.isArray(d.checks)) return null
  const written = Date.parse(text(d.at) ?? '')
  const passed = Date.parse(phase.from ? '' : text(phase.updatedAt) ?? '')
  if (phase.status === 'complete' && written < passed) return null
  return d.checks.flatMap(value => {
    const c = record(value)
    const id = text(c.id)
    return id === null ? [] : [{
      id, label: text(c.label) ?? id, status: text(c.status) ?? 'waiting', message: text(c.message),
      dependsOn: Array.isArray(c.dependsOn) ? c.dependsOn.filter((x): x is string => typeof x === 'string') : [],
    }]
  })
}

/** Preflight passed and every check is done: the group can fold to one line. */
export function preflightPassed(summary: Summary): boolean {
  const p = summary.preflight
  return p?.status === 'complete' && (p.checks ?? []).every(check => check.status === 'done')
}

/** What a check says beside its label: only while it is working or needs something. */
export function checkMessage(check: Check): string | null {
  return ['checking', 'needs-you', 'failed'].includes(check.status) ? check.message : null
}

/** HH:MM on the person's clock. */
export function clockOf(stamp: string | null): string | null {
  if (!stamp) return null
  const at = new Date(stamp)
  if (Number.isNaN(at.getTime())) return null
  return `${String(at.getHours()).padStart(2, '0')}:${String(at.getMinutes()).padStart(2, '0')}`
}

/** The recap belongs to this build: its scorecard names the build's creation, or, from a scorer
 * before that stamp, the build has recorded its benchmark as complete. A folder initialised again
 * keeps the old benchmark/ folder until it is scored, and that must not read as done. */
export function recapIsCurrent(project: Record<string, unknown>, raw: Raw): boolean {
  if (raw.completion === undefined) return false
  const stamp = record(record(raw.scorecard).run).buildCreatedAt
  if (typeof stamp === 'string') return stamp === text(project.createdAt)
  return text(record(record(project.phases).benchmark).status) === 'complete'
}

/** The completion message as written, cut with a note if it ever outgrows what Markdown draws. */
export function recapOf(completion: string): string {
  const text = completion.trim()
  return text.length <= RECAP_LIMIT ? text : `${text.slice(0, RECAP_LIMIT)}\n\n(cut here: the whole message is in benchmark/completion.md)`
}

/** Finished: the scorer has written this build's recap. The runner reports done once the Figma
 * build is over, while verification and scoring still have to run. */
export function isFinished(summary: Summary): boolean {
  return summary.hasRecap
}

/** The run is stopped for the person: building or checking, and the runner is gone. */
export function isDown(summary: Summary): boolean {
  if (!summary.found || isFinished(summary)) return false
  if (summary.blocker) return true
  const runner = summary.runner
  return runner !== null && (runner.state === 'building' || runner.state === 'preflight') && !runner.connected
}

/** Before the build starts, or between builds, the runner is not needed: idle, not missing. */
export function isIdle(runner: Runner): boolean {
  return runner.state === 'waiting' && !runner.connected
}

export function runnerLine(runner: Runner): string {
  if (runner.state === 'done') return 'Figma build finished'
  if (!runner.serverAlive) return 'runner server not responding'
  if (runner.connected) return 'runner connected'
  if (isIdle(runner)) return 'runner idle until the build'
  if (runner.state === 'connecting') return 'waiting for the runner to start'
  const minutes = Math.max(1, Math.round((runner.lastSeenMs ?? 0) / 60_000))
  return `runner not seen for ${minutes}m`
}

export function stepsLine(runner: Runner): string | null {
  if ((runner.state === 'building' || runner.state === 'done') && runner.stepsTotal) {
    const kind = runner.state === 'building' && runner.stepKind ? `, ${runner.stepKind}` : ''
    return `steps ${runner.stepsDone ?? 0}/${runner.stepsTotal}${kind}`
  }
  // The server's last word to a runner that has since gone quiet ("Connected. Waiting…") is stale.
  return isIdle(runner) || runner.state === 'connecting' ? null : runner.message
}

/** A length of time as the pane writes it: 41m, 3h 44m; under a minute, 40s. */
export function durationOf(seconds: number | null): string | null {
  if (seconds === null || seconds < 0) return null
  if (seconds < 60) return `${Math.round(seconds)}s`
  // Rounded, as the recap rounds it, so the two agree.
  const minutes = Math.round(seconds / 60)
  return minutes < 60 ? `${minutes}m` : `${Math.floor(minutes / 60)}h ${minutes % 60}m`
}

/** How long the run has been going, from its start. */
export function elapsedOf(startedAt: string | null, nowMs: number): string | null {
  const ms = msSince(startedAt, nowMs)
  if (ms === null || ms < 0) return null
  return ms < 60_000 ? '0m' : durationOf(Math.floor(ms / 60_000) * 60)
}

/** The scorecard's headline figures; null when there is no scorecard to read. */
export function scoresOf(scorecard: unknown): Scores | null {
  const card = record(scorecard)
  if (!('headline' in card)) return null
  const headline = record(card.headline)
  const coverage = record(headline.coverage)
  const accuracy = record(record(headline.accuracy).corrected)
  const effort = record(headline.effort)
  const open = record(record(record(card.sections).conformance).open)
  return {
    built: count(coverage.built),
    eligible: count(coverage.eligible),
    withinTolerance: count(accuracy.pass),
    widths: count(accuracy.total),
    workingSeconds: count(effort.workingSeconds),
    buildSeconds: count(effort.buildSeconds),
    buildSteps: count(effort.buildSteps),
    tokens: count(effort.tokens),
    toolCalls: count(effort.toolCalls),
    blockers: count(open.blocker),
    majors: count(open.major),
  }
}

/** The first Figma file link in the recap, without the punctuation of the sentence it ends. */
export function figmaUrlOf(completion: string): string | null {
  return /https:\/\/www\.figma\.com\/(?:design|file)\/[^\s)>\]]+/.exec(completion)?.[0].replace(/[.,;:]+$/, '') ?? null
}

/** 40013109 as 40.0M, 563519 as 564K. */
export function compactOf(value: number | null): string | null {
  if (value === null) return null
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`
  if (value >= 1_000) return `${Math.round(value / 1_000)}K`
  return String(value)
}

/** A share as a whole percent, or null with nothing to divide by. Anything short of the whole
 * stays below 100, so 200 of 201 reads 99% and is never judged complete. */
export function percentOf(part: number | null, whole: number | null): number | null {
  if (part === null || !whole) return null
  const percent = Math.round((part / whole) * 100)
  return part < whole && percent >= 100 ? 99 : percent
}

/** A bar of `cells` cells, filled in proportion: the filled run and the empty run, drawn apart. */
export function barOf(done: number, total: number, cells: number): { filled: string; empty: string } {
  const width = Math.max(4, cells)
  const share = total > 0 ? Math.min(1, Math.max(0, done / total)) : 0
  const filled = Math.round(share * width)
  return { filled: '━'.repeat(filled), empty: '━'.repeat(width - filled) }
}

/** Where the run stands, in one word, and the color it is drawn in. */
export type Tone = { label: string; color: string }

export function toneOf(summary: Summary): Tone {
  const stages = stagesOf(summary)
  if (stages.some(stage => stage.state === 'failed')) return { label: 'Failed', color: 'red' }
  if (needsYouOf(summary)) return { label: 'Needs you', color: 'yellow' }
  if (isFinished(summary)) {
    return verdictOf(summary.findings) ? { label: 'Done · needs review', color: 'yellow' } : { label: 'Done', color: 'green' }
  }
  const active = stages.find(stage => stage.state === 'active' || stage.state === 'stopped')
  return { label: active?.doing ?? 'Starting', color: 'cyan' }
}

/** What the person has to do, from one place, so the header, the card, the stage and the toast
 * always agree; null when the run needs nothing from them. */
export function needsYouOf(summary: Summary): { message: string; canResume: boolean } | null {
  // A failure outranks every request: the Failed card says what went wrong, and resuming would
  // only run into it again.
  if (hasFailed(summary)) return null
  if (summary.blocker) return { message: summary.blocker, canResume: true }
  if (summary.waiting) return { message: summary.waiting, canResume: false }
  const check = (summary.preflight?.checks ?? []).find(c => c.status === 'needs-you')
  if (check) return { message: `${check.label}: ${check.message ?? 'needs your attention'}`, canResume: false }
  if (isDown(summary)) {
    return { message: 'The Figma runner has stopped. Reopen it in Figma desktop, then press Resume run.', canResume: true }
  }
  return null
}

/** Something failed: a phase run here, the runner while the run is unfinished, or a preflight check. */
export function hasFailed(summary: Summary): boolean {
  return summary.phases.some(phase => !phase.reused && phase.status === 'failed')
    || (summary.runner?.state === 'failed' && !isFinished(summary))
    || (summary.preflight?.checks ?? []).some(check => check.status === 'failed')
}

/** The first stage that failed, and what the card says about it; null when nothing failed. */
export function failureOf(summary: Summary): { stage: string; text: string } | null {
  const stage = stagesOf(summary).find(s => s.state === 'failed')
  if (!stage) return null
  const check = stage.id === 'preflight' ? (summary.preflight?.checks ?? []).find(c => c.status === 'failed') : undefined
  const phase = stage.phases.find(p => !p.reused && p.status === 'failed')
  const message = check ? (check.message ? `${check.label}: ${check.message}` : check.label)
    : (phase && summary.phaseErrors[phase.name]) ?? (stage.id === 'build' && summary.runner?.state === 'failed' ? summary.runner.message : null)
  return { stage: stage.label, text: message
    ? `${stage.label} stopped with an error: ${message}`
    : `${stage.label} stopped with an error. Ask Claude in the conversation what went wrong.` }
}

/** What the verdict card says when verification left blocking or major problems open; null otherwise. */
export function verdictOf(findings: Findings | null): string | null {
  if (!findings || findings.blocker + findings.major === 0) return null
  const { blocker, major } = findings
  const parts = [blocker ? `${blocker} blocking` : null, major ? `${major} major` : null].filter(Boolean)
  const one = blocker + major === 1
  return `${parts.join(' and ')} problem${one ? ' is' : 's are'} still open, so the library does not yet meet the design-lab standard.`
}

/** A phase name as a person reads it: figma-build as Figma build. */
export function phaseLabel(name: string): string {
  const words = name.replace(/[-_]/g, ' ')
  return words.charAt(0).toUpperCase() + words.slice(1)
}

export const PHASE_DONE = DONE

/** The status line, or undefined to clear it once the run is over or gone. */
export function statusOf(summary: Summary, nowMs: number): string | undefined {
  if (!summary.found) return undefined
  if (isFinished(summary)) return undefined
  // The engine shows the plugin's name before it: `design-lab: steps 112/158 · runner connected · 41m`.
  const parts: string[] = []
  const runner = summary.runner
  const checks = summary.preflight?.checks
  if (runner?.state === 'building' && runner.stepsTotal) parts.push(`steps ${runner.stepsDone ?? 0}/${runner.stepsTotal}`)
  else if (checks && summary.preflight?.status !== 'complete') {
    parts.push(`preflight ${checks.filter(check => check.status === 'done').length}/${checks.length}`)
  } else if (summary.current) parts.push(summary.current)
  if (runner) parts.push(runnerLine(runner))
  const time = elapsedOf(summary.startedAt, nowMs)
  if (time) parts.push(time)
  return parts.length > 0 ? parts.join(' · ') : undefined
}

/** The whole summary as plain text: the command's answer where nothing draws. */
export function plainOf(summary: Summary): string {
  if (!summary.found) return `No design-lab run in ${summary.workspace}: it has no project.json.`
  const lines = [`design-lab · ${summary.siteLabel ?? summary.workspace}`, '']
  const checks = summary.preflight?.checks
  if (checks && checks.length > 0) {
    lines.push('  Preflight')
    for (const check of checks) {
      const message = checkMessage(check)
      lines.push(`    ${CHECK_MARKS[check.status] ?? '·'} ${check.label}${message ? `: ${message}` : ''}`)
    }
    lines.push('')
  }
  for (const phase of summary.phases) {
    const mark = DONE.has(phase.status) ? '✓' : phase.status === 'failed' ? '✗' : phase.name === summary.current ? '▸'
      : phase.status === 'stopped' ? '!' : '·'
    lines.push(`  ${mark} ${phase.name}`)
  }
  if (summary.runner) {
    const steps = stepsLine(summary.runner)
    lines.push('')
    if (steps) lines.push(`  ${steps}`)
    if (!summary.hasRecap) lines.push(`  ${runnerLine(summary.runner)}`)
  }
  const failure = failureOf(summary)
  if (failure) lines.push('', `  Failed: ${failure.text}`)
  const need = needsYouOf(summary)
  if (need) lines.push('', `  Needs you: ${need.message}`)
  if (summary.hasRecap) lines.push('', `  Recap: ${summary.workspace}/benchmark/completion.md`)
  return lines.join('\n')
}

/**
 * What the resume button does after asking to fill the prompt box: nothing more once filled;
 * send the request where the session has no prompt box at all; otherwise (a dialog holds the
 * keys, or the reason is unknown) leave the person's draft alone and say why.
 */
export function afterFill(filled: { isFilled: boolean; refusal?: string } | undefined): 'done' | 'submit' | 'explain' {
  if (filled?.isFilled) return 'done'
  return filled?.refusal === 'no_composer' ? 'submit' : 'explain'
}

export const RESUME_PROMPT = (workspace: string) =>
  `The design-lab runner is open again in Figma desktop. Resume the design-lab run in ${workspace} from where it stopped.`

/** What the phases recorded about the run: counts from inventory, plan and components, the file
 * from connect (or, failing that, the recap). */
export function factsOf(project: Record<string, unknown>, completion: string | undefined): Facts {
  const phases = record(project.phases)
  const detail = (name: string) => record(record(phases[name]).detail)
  return {
    found: count(detail('inventory').components),
    toBuild: count(detail('plan').build),
    built: count(detail('components').built),
    expected: count(detail('components').expected),
    figmaUrl: text(detail('connect').fileUrl) ?? (completion ? figmaUrlOf(completion) : null),
  }
}

/** The open findings by severity, or null before this run's verification has written its report.
 * A folder initialised again keeps the last run's report, so one written before this run began is
 * not this run's. */
export function findingsOf(report: unknown, createdAt: string | null): Findings | null {
  const r = record(report)
  if (!Array.isArray(r.open) || !Array.isArray(r.passed)) return null
  const written = Date.parse(text(r.generatedAt) ?? '')
  if (Number.isNaN(written) || written < Date.parse(createdAt ?? '')) return null
  const by = (severity: string) => (r.open as unknown[]).filter(f => record(f).severity === severity).length
  return { blocker: by('blocker'), major: by('major'), minor: by('minor'), passed: r.passed.length,
    waived: Array.isArray(r.waived) ? r.waived.length : 0 }
}

/** The five stages a run moves through, and the phases each holds. A phase not named here
 * belongs to Build, so nothing the run records goes unshown. */
export const STAGES = [
  { id: 'preflight', label: 'Preflight', doing: 'Preflight', phases: ['preflight'] },
  { id: 'discovery', label: 'Discovery', doing: 'Discovering', phases: ['discovery', 'inventory', 'usage', 'capture', 'tokens', 'plan'] },
  { id: 'build', label: 'Build', doing: 'Building', phases: ['connect', 'foundation', 'components', 'index'] },
  { id: 'verify', label: 'Verify', doing: 'Verifying', phases: ['verify'] },
  { id: 'report', label: 'Report', doing: 'Reporting', phases: ['benchmark'] },
] as const

export type StageId = (typeof STAGES)[number]['id']
// flagged: finished with open blocking or major problems; failed: stopped with an error.
export type StageState = 'done' | 'flagged' | 'active' | 'stopped' | 'failed' | 'pending' | 'reused'
export type Stage = { id: StageId; label: string; doing: string; state: StageState; phases: Phase[]; note: string | null; noteColor?: string }

// Every known phase in the order the run takes them. A phase not named here sits just after index,
// so it stays with Build and comes before verify.
const FLOW: string[] = STAGES.flatMap(stage => [...stage.phases])
const BUILD_PHASES = new Set<string>(STAGES.find(stage => stage.id === 'build')!.phases)

function flowRank(name: string): number {
  const at = FLOW.indexOf(name)
  return at >= 0 ? at : FLOW.indexOf('index') + 0.5
}

function stageOf(name: string): StageId {
  return STAGES.find(stage => (stage.phases as readonly string[]).includes(name))?.id ?? 'build'
}

const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`

function stageNote(id: StageId, state: StageState, summary: Summary, phases: Phase[]): { note: string | null; noteColor?: string } {
  const f = summary.facts
  if (state === 'reused') return { note: 'reused from an earlier run' }
  if (state === 'pending') return { note: null }
  if (id === 'preflight') {
    const checks = summary.preflight?.checks
    if (!checks) return { note: state === 'done' ? 'passed' : null }
    const done = checks.filter(check => check.status === 'done').length
    return { note: state === 'done' ? `${checks.length} checks passed` : `${done} of ${checks.length} checks` }
  }
  if (id === 'discovery') {
    if (state !== 'done') return { note: `${phases.filter(phase => DONE.has(phase.status)).length} of ${phases.length} steps` }
    const parts = [f.found !== null ? `${f.found} found` : null, f.toBuild !== null ? `${f.toBuild} planned` : null].filter(Boolean)
    return { note: parts.length ? parts.join(' · ') : 'complete' }
  }
  if (id === 'build') {
    const runner = summary.runner
    if (state !== 'done' && runner?.state === 'building' && runner.stepsTotal) return { note: `${percentOf(runner.stepsDone ?? 0, runner.stepsTotal)}%` }
    if (f.built !== null && f.expected !== null) {
      return { note: `${f.built} of ${f.expected} planned built`, noteColor: state === 'done' && f.built < f.expected ? 'yellow' : undefined }
    }
    return { note: state === 'done' ? 'complete' : null }
  }
  if (id === 'verify') {
    const k = summary.findings
    if (!k || (state !== 'done' && state !== 'flagged')) return { note: null }
    // Kept short so the row fits a narrow pane; the verdict card above the figures has the rest.
    if (state === 'flagged') {
      const parts = [k.blocker ? plural(k.blocker, 'blocker', 'blockers') : null, k.major ? `${k.major} major` : null].filter(Boolean)
      return { note: `${parts.join(' · ')} open`, noteColor: 'yellow' }
    }
    if (k.minor > 0) return { note: `${k.minor} minor open`, noteColor: 'yellow' }
    // Checks that do not apply to this site are not problems, so the note leaves them out.
    return { note: k.waived === 0 ? `all ${k.passed} checks pass` : `${k.passed} passed · ${k.waived} waived`, noteColor: 'green' }
  }
  return { note: state === 'done' ? 'report ready' : null }
}

/** Each stage with where it stands, first match winning: copied from an earlier run, failed, done
 * (flagged when verification left problems open), stopped for the person, under way, not started.
 * A stage is under way when it holds the run's current phase or any of its phases is running, so
 * more than one can be. */
export function stagesOf(summary: Summary): Stage[] {
  const finished = isFinished(summary)
  const need = needsYouOf(summary)
  const checks = summary.preflight?.checks ?? []
  const k = summary.findings
  return STAGES.map(def => {
    // summary.phases is already in flow order.
    const phases = summary.phases.filter(phase => stageOf(phase.name) === def.id)
    const own = phases.filter(phase => !phase.reused)
    const running = own.some(phase => phase.status === 'running')
    const holdsCurrent = phases.some(phase => phase.name === summary.current)
    const failed = own.some(phase => phase.status === 'failed')
      || (def.id === 'build' && summary.runner?.state === 'failed' && !finished)
      || (def.id === 'preflight' && checks.some(check => check.status === 'failed'))
    // Once the recap is written the run is over: a stage whose phase record never caught up
    // (verify left 'running', say) is still done, and Verify is judged by its findings.
    const done = (phases.length > 0 && phases.every(phase => DONE.has(phase.status))) || finished
    let state: StageState
    if (phases.length > 0 && phases.every(phase => phase.reused) && !phases.some(phase => phase.status === 'running')) state = 'reused'
    else if (failed) state = 'failed'
    else if (done) state = def.id === 'verify' && k && k.blocker + k.major > 0 ? 'flagged' : 'done'
    else if ((holdsCurrent || running) && !finished) {
      const stopped = (need !== null && holdsCurrent) || (def.id === 'preflight' && checks.some(check => check.status === 'needs-you'))
        || phases.some(phase => phase.status === 'stopped')
      state = stopped ? 'stopped' : 'active'
    } else state = 'pending'
    return { id: def.id, label: def.label, doing: def.doing, state, phases, ...stageNote(def.id, state, summary, phases) }
  })
}

